query:
PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT ?empresa (SUM(?gas_concesion * ?pct / 100) AS ?gas_que_le_corresponde_miles_m3)
WHERE {
  ?c energia:name ?empresa .
  FILTER(?empresa = "TOTAL AUSTRAL S.A.")
  ?s a energia:Stake ;
     energia:partner ?c ;
     energia:percent ?pct ;
     energia:inConcession ?con .
  {
    SELECT ?con (SUM(?g) AS ?gas_concesion)
    WHERE {
      ?p a energia:WellProduction ;
         energia:inConcession ?con ;
         energia:gas ?g .
    }
    GROUP BY ?con
  }
}
GROUP BY ?empresa
LIMIT 50
